function sum(num1, num2) {
  // Walk from num1 one unit at a time, |num2| steps in num2's direction.
  let value = num1;
  const step = num2 < 0 ? -1 : 1;
  for (let moved = 0; moved !== num2; moved += step) value += step;
  return value;
}

