function generate(rand, size) {
  const pickValue = () => {
    const roll = rand();
    if (size === 'small' && roll < 0.15) return 0;
    if (roll < 0.3) return rand() < 0.5 ? 100 : -100;
    return Math.floor(rand() * 201) - 100;
